        "A proper scoring rule that rewards both calibration and sharpness jointly",
        "A misclassification measure equal to the absolute error of the point estimate",
        "The total variance of observed outcomes across the entire validation sample",
        "The ROC-curve area multiplied by the prevalence of the outcome condition"
